/**
 * Returns dataset metadata only (no geojson payload). Use the detail endpoint to download. When `lat` and `lng` are supplied, results are the nearest datasets to that point; otherwise they are newest-first. Always capped by `limit` so clients never fetch the entire library at once.
 * @summary List community datasets
 */
export const getListCommunityDatasetsUrl = (
  params?: ListCommunityDatasetsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/community/datasets?${stringifiedParams}`
    : `/api/community/datasets`;
};

export const listCommunityDatasets = async (
  params?: ListCommunityDatasetsParams,
  options?: RequestInit,
): Promise<CommunityDatasetSummary[]> => {
  return customFetch<CommunityDatasetSummary[]>(
    getListCommunityDatasetsUrl(params),
    {
      ...options,
      method: "GET",
    },
  );
};

